(() => {
  'use strict';
  const C = window.CATALOG;
  const bank = [...C.checks, ...window.QUESTION_BANK];
  const questionById = new Map(bank.map(q => [q.id, q]));
  const lessonById = new Map(C.lessons.map(l => [l.id, l]));
  const KEY = 'devpath-workspace-v2';
  const LEGACY = 'learning-space-state-v1';
  const $ = s => document.querySelector(s);
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const now = () => new Date().toISOString();
  const dayKey = (d = new Date()) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const defaultState = () => ({version:2,profile:{track:'java',hours:8,minutes:30},lessons:{},projects:{},notes:[],quizHistory:[],wrong:{},events:[],bookmarks:[],interview:{},talkDrafts:{},jobDraft:{title:'',text:'',notes:''},resume:{},draftNote:'',lastLesson:'j-run',quizSession:null,legacy:null});
  let state = defaultState(), storageError = false, unreadableRecord = null;
  try {
    const saved = localStorage.getItem(KEY);
    if(saved) state = normalize(JSON.parse(saved));
    else {
      const old = JSON.parse(localStorage.getItem(LEGACY) || 'null');
      if(old && typeof old === 'object') {
        state.legacy = old;
        if(C.tracks[old.track]) state.profile.track = old.track;
        if([15,30,60].includes(old.selectedMinutes)) state.profile.minutes = old.selectedMinutes;
        if(Array.isArray(old.notes)) state.notes = old.notes.map((n,i)=>({id:'migrated-'+i,title:String(n.type||'历史问题'),body:['现象：'+(n.actual||''),'期待：'+(n.expected||''),'尝试：'+(n.tried||''),'下一步：'+(n.next||'')].join('\n'),date:now(),lesson:''}));
      }
    }
  } catch { storageError = true; try { unreadableRecord = localStorage.getItem(KEY); } catch {} }
  let quizFilters = {track:'java',topic:'all',kind:'all',count:10};
  let quizResult = null, projectFilter = 'all', projectSearch = '', interviewFilter = 'all';
  let route = [], toastTimer;
  const main = $('#main'), dialog = $('#dialog');
  function isObject(v){return v && typeof v==='object' && !Array.isArray(v);}
  function bounded(v,max=20000) { return typeof v==='string' ? v.slice(0,max) : ''; }
  function normalize(raw) {
    if(!isObject(raw) || raw.version!==2) throw new Error('不是有效的 v2 学习备份');
    const s=defaultState();
    if(C.tracks[raw.profile?.track]) s.profile.track=raw.profile.track;
    s.profile.hours = Math.max(1,Math.min(40,Number(raw.profile?.hours)||8));
    if([15,30,60].includes(raw.profile?.minutes)) s.profile.minutes=raw.profile.minutes;
    for(const l of C.lessons){const v=raw.lessons?.[l.id];if(isObject(v)) s.lessons[l.id]={read:!!v.read,practiced:!!v.practiced,evidence:bounded(v.evidence),checks:Array.from({length:3},(_,i)=>!!v.checks?.[i]),answer:Number.isInteger(v.answer)&&v.answer>=0&&v.answer<l.options.length?v.answer:null,correct:!!v.correct,help:['independent','hint','reference'].includes(v.help)?v.help:'independent',date:bounded(v.date,40)};}
    for(const p of C.projects){const v=raw.projects?.[p.id];if(isObject(v)) s.projects[p.id]={steps:p.steps.map((_,i)=>!!v.steps?.[i]),evidence:bounded(v.evidence),started:!!v.started};}
    if(Array.isArray(raw.notes)) s.notes=raw.notes.slice(0,500).filter(isObject).map((n,i)=>({id:'restored-'+i+'-'+Date.now(),title:bounded(n.title,120),body:bounded(n.body),date:bounded(n.date,40),lesson:lessonById.has(n.lesson)?n.lesson:''}));
    if(Array.isArray(raw.quizHistory)) s.quizHistory=raw.quizHistory.slice(-200).filter(h=>isObject(h)&&Number.isFinite(h.score)&&Number.isFinite(h.total)&&h.score>=0&&h.total>0&&h.score<=h.total).map(h=>({date:bounded(h.date,40),score:h.score,total:h.total,track:bounded(h.track,30),ids:Array.isArray(h.ids)?h.ids.filter(id=>questionById.has(id)):[]}));
    for(const q of bank){const v=raw.wrong?.[q.id];if(isObject(v)) s.wrong[q.id]={count:Math.max(1,Math.min(10000,Number(v.count)||1)),date:bounded(v.date,40)};}
    if(Array.isArray(raw.events)) s.events=raw.events.slice(-1000).filter(e=>isObject(e)&&/^\d{4}-\d{2}-\d{2}$/.test(e.day)).map(e=>({day:e.day,type:bounded(e.type,40),id:bounded(e.id,80),date:bounded(e.date,40)}));
    if(Array.isArray(raw.bookmarks)) s.bookmarks=raw.bookmarks.filter(id=>lessonById.has(id));
    for(const i of C.interview) s.interview[i.id]=bounded(raw.interview?.[i.id]);
    for(const q of window.INTERVIEW_BANK){const d=raw.talkDrafts?.[q.id];if(isObject(d)){const checks=[0,1,2].map(i=>!!d.checks?.[i]),answer=bounded(d.answer,12000);let rating=['weak','developing','ready'].includes(d.rating)?d.rating:'new';if(rating==='ready'&&(!checks.every(Boolean)||answer.trim().length<24))rating='developing';s.talkDrafts[q.id]={answer,checks,rating,favorite:!!d.favorite,date:bounded(d.date,40)};}}
    s.jobDraft={title:bounded(raw.jobDraft?.title,120),text:bounded(raw.jobDraft?.text,16000),notes:bounded(raw.jobDraft?.notes,6000)};
    for(const k of ['project','role','decision','evidence','limitation']) s.resume[k]=bounded(raw.resume?.[k]);
    s.draftNote=bounded(raw.draftNote);if(lessonById.has(raw.lastLesson))s.lastLesson=raw.lastLesson;
    if(isObject(raw.legacy))s.legacy=raw.legacy;
    const quiz=raw.quizSession;
    if(isObject(quiz)&&Array.isArray(quiz.items)&&quiz.items.length>0&&quiz.items.length<=50&&quiz.items.every(i=>isObject(i)&&questionById.has(i.id)&&Array.isArray(i.order)&&i.order.length===questionById.get(i.id).options.length&&new Set(i.order).size===i.order.length&&i.order.every(n=>Number.isInteger(n)&&n>=0&&n<i.order.length))){
      s.quizSession={track:bounded(quiz.track,30),index:Math.max(0,Math.min(quiz.items.length-1,Number(quiz.index)||0)),items:quiz.items.map(i=>({id:i.id,order:i.order})),answers:{},started:bounded(quiz.started,40)};
      for(const i of quiz.items){const a=quiz.answers?.[i.id];if(Number.isInteger(a)&&a>=0&&a<i.order.length)s.quizSession.answers[i.id]=a;}
    }
    return s;
  }
  function save(){try{if(unreadableRecord){localStorage.setItem(KEY+'-unreadable-'+Date.now(),unreadableRecord);unreadableRecord=null;}localStorage.setItem(KEY,JSON.stringify(state));storageError=false;return true;}catch{storageError=true;toast('本机存储不可用或已满，内容仍在当前页面，请先导出备份。');return false;}}
  function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
  function event(type,id){state.events.push({type,id,date:now(),day:dayKey()});state.events=state.events.slice(-1000);}
  function progress(id){return state.lessons[id]||{read:false,practiced:false,evidence:'',checks:[false,false,false],answer:null,correct:false,help:'independent'};}
  function independent(id){const p=progress(id);return p.practiced&&p.correct&&p.checks?.every(Boolean)&&p.evidence.trim().length>=12&&p.help==='independent';}
  function nextLesson(track=state.profile.track){const list=C.lessons.filter(l=>l.track===track);return list.find(l=>!independent(l.id))||list[0];}
  function resumeLesson(){const last=lessonById.get(state.lastLesson);return last&&last.track===state.profile.track&&!independent(last.id)?last:nextLesson();}
  function pct(n,d){return d?Math.round(n/d*100):0;}
  function badge(text,cls=''){return `<span class="pill ${cls}">${esc(text)}</span>`;}
  function link(text,href,cls='button'){return `<a class="${cls}" href="${esc(href)}">${text}</a>`;}
  function button(text,action,cls='button',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;}
  function heading(label,title,sub,action=''){return `<div class="page-heading"><div><div class="label">${label}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
  function empty(title,copy){return `<div class="empty-state"><strong>${title}</strong>${copy}</div>`;}
  const icons={home:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',roadmap:'<path d="M5 5h14v5H5zM12 10v5M5 19v-4h14v4M2 19h6v3H2zM16 19h6v3h-6z"/>',projects:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18M10 12v3h4v-3"/>',quiz:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="m8 9 2 2 4-4M8 15h8M8 18h5"/>',review:'<path d="M4 8a9 9 0 1 1-1 8M4 3v5h5M12 7v5l3 2"/>',interview:'<path d="M4 3h16v14H9l-5 4zM8 8h8M8 12h5"/>',notes:'<path d="M4 3h12v18H4zM8 7h4M8 11h4M20 5v12M18 19h4"/>',resources:'<path d="M12 6c-4-3-8-2-9-1v15c4-2 7-1 9 1 2-2 5-3 9-1V5c-2-1-6-2-9 1zm0 0v15"/>'};
  const navItems=[['home','学习概览'],['roadmap','学习路线'],['projects','项目工坊'],['quiz','测验题库'],['review','错题复习'],['interview','面试训练'],['job','岗位对照'],['portfolio','项目表达'],['notes','笔记与成果'],['resources','学习资料']];
  icons.job='<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6z"/>';
  icons.portfolio='<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>';
  function renderNav(){const active=route[0]==='lesson'?'roadmap':route[0]==='project'?'projects':route[0];$('#nav').innerHTML=navItems.map(([id,name],i)=>`${i===5?'<div class="nav-divider">求职与成长</div>':''}<a class="nav-link ${active===id?'active':''}" ${active===id?'aria-current="page"':''} href="#${id}"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[id]}</svg>${name}${id==='review'&&Object.keys(state.wrong).length?`<em>${Object.keys(state.wrong).length}</em>`:''}</a>`).join('');$('#crumb').textContent=navItems.find(([id])=>id===active)?.[1]||'学习空间';$('#sidebarGoal').textContent=C.tracks[state.profile.track].short+' · 每周 '+state.profile.hours+'h';}
  function navigate(){route=location.hash.slice(1).split('/');if(!route[0])route=['home'];if(!navItems.some(n=>n[0]===route[0])&&!['lesson','project'].includes(route[0]))route=['home'];dialog.close();$('#sidebar').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');render();window.scrollTo(0,0);}
  function render(){career.stopTimer();renderNav();({home:home,roadmap:roadmap,lesson:lesson,projects:projects,project:project,quiz:quiz,review:review,interview:()=>career.render(route),job:career.job,portfolio:portfolio,notes:notes,resources:resources}[route[0]]||home)();}
  function home(){
    const next=resumeLesson(), learned=Object.values(state.lessons).filter(l=>l.read).length, practical=C.lessons.filter(l=>independent(l.id)).length;
    const started=Object.values(state.projects).filter(p=>p.started).length;
    const date=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});
    const pending=Object.keys(state.wrong).length;
    const minutes=state.profile.minutes;
    const tasks=minutes===15?[['读懂核心概念','5 分钟 · 写下一句自己的理解'],['追踪示例输入与输出','10 分钟 · 保存暂停位置']]:minutes===30?[['读懂今天的知识','8 分钟 · 明确业务用途'],['在本机运行示例','17 分钟 · 更改一项输入'],['保存结果与疑问','5 分钟 · 留下下一步']]:[['学习并运行示例','20 分钟 · 观察预期结果'],['独立完成变式','30 分钟 · 测试边界条件'],['自测与复盘','10 分钟 · 保存实践证据']];
    const dates=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return d;});const counts=dates.map(d=>state.events.filter(e=>e.day===dayKey(d)).length);const max=Math.max(1,...counts);
    main.innerHTML=heading('MY LEARNING DESK','今天，从一个小成果开始。','先学明白，再独立完成。你的下一份作品，从这里继续。',`<span class="date">${date}</span>`)+
    `<div class="overview-grid"><div><section class="panel hero"><div><div class="eyebrow">继续学习 / ${C.tracks[next.track].short}</div><h2>${next.title}</h2><p>${next.goal}</p><div class="actions">${link('开始今天的学习 <span>↗</span>','#lesson/'+next.id,'button primary')}${link('查看完整路线','#roadmap/'+next.track,'text-button')}</div></div><div class="hero-code" aria-hidden="true"><div class="code-dots"><i></i><i></i><i></i></div><span class="code-muted">// one step at a time</span><br><span class="code-accent">learn</span>(concept);<br><span class="code-accent">build</span>(something);<br><span class="code-accent">test</span>(yourself);<br><br><span class="code-muted">return</span> progress;</div></section>
    <div class="stats-row">${[['⌘',learned,'已阅读课程'],['✓',practical,'独立练习自检'],['↗',started,'进行中的项目'],['◎',pending,'待复习错题']].map(([i,n,t])=>`<div class="panel stat"><span class="stat-symbol">${i}</span><div><b>${n}</b><small>${t}</small></div></div>`).join('')}</div>
    <section class="panel"><div class="panel-heading"><div><h2>你的技术成长路线</h2><p>选一个方向专注推进，也可以随时学习其他路线。</p></div>${link('全部路线 ↗','#roadmap','text-button')}</div><div class="track-cards">${['java','python','crawler'].map(k=>{const t=C.tracks[k],ls=C.lessons.filter(l=>l.track===k),n=ls.filter(l=>independent(l.id)).length;return `<article class="track-card"><div class="card-top"><span class="track-icon ${k}">${t.icon}</span>${badge(t.tag,k==='java'?'orange':k==='python'?'blue':'green')}</div><h3>${t.name}</h3><p>${t.desc}</p><div class="progress-track"><span style="width:${pct(n,ls.length)}%"></span></div><div class="progress-caption"><span>${n} / ${ls.length} 节实践自检</span><span>${pct(n,ls.length)}%</span></div>${link('进入路线 →','#roadmap/'+k,'text-button')}</article>`;}).join('')}</div></section>
    <section class="panel section-spaced"><div class="panel-heading"><div><h2>把知识用起来</h2><p>本周可以开始的一份小作品</p></div>${link('项目工坊 ↗','#projects','text-button')}</div>${C.projects.filter(p=>p.track===state.profile.track).slice(0,2).map((p,i)=>`<a class="next-row" href="#project/${p.id}"><span class="row-number">0${i+1}</span><div><h3>${p.title}</h3><p>${p.tags.join(' / ')} · ${p.time}${p.pack?' · 含本地练习包':''}</p></div><span class="row-link">↗</span></a>`).join('')}</section></div>
    <aside><section class="panel focus-plan"><div class="panel-heading"><h2>今天的专注计划</h2>${badge('可调整')}</div><div class="segmented">${[15,30,60].map(n=>button(n+' 分钟','minutes',n===minutes?'selected':'',`data-minutes="${n}" aria-pressed="${n===minutes}"`)).join('')}</div><div class="plan-steps">${tasks.map((t,i)=>`<div class="plan-step"><b class="step-no">${i+1}</b><div><strong>${t[0]}</strong><span>${t[1]}</span></div></div>`).join('')}</div>${link(minutes===15?'开始一个小步骤 →':'开始专注学习 →','#lesson/'+next.id,'button primary full')}</section>
    <section class="panel section-spaced"><div class="panel-heading"><h2>最近 7 天</h2>${badge('学习动作')}</div><div class="week-bars">${dates.map((d,i)=>`<div class="week-bar ${i===6?'today':''}" title="${dayKey(d)}：${counts[i]} 次保存"><span class="bar" style="height:${Math.max(4,counts[i]/max*64)}px"></span><small>${['日','一','二','三','四','五','六'][d.getDay()]}</small></div>`).join('')}</div><p class="activity-caption">${counts.reduce((a,b)=>a+b,0)} 次阅读、练习或复盘记录。${counts.every(n=>!n)?'完成第一次学习后，这里会记录你的足迹。':'每一步都来自你实际保存的记录。'}</p></section>
    <section class="panel tip-panel section-spaced"><div class="eyebrow">面试训练 / ${window.INTERVIEW_BANK.length} 道开放式题目</div><h3>会写，也要讲得清。</h3><p>为什么这样设计？还有什么边界？用两分钟练一道题，再看参考思路。</p>${link('开始面试训练 →','#interview','text-button')}</section></aside></div><a class="interview-banner-link" href="#job"><div><strong>不确定下一步该学什么？对照一份想投的岗位。</strong><p>把招聘要求连接到课程、项目与面试题，先补最相关的基础。</p></div><span aria-hidden="true">→</span></a>`;
  }
  function roadmap(){const key=C.tracks[route[1]]?route[1]:state.profile.track,t=C.tracks[key],list=C.lessons.filter(l=>l.track===key),done=list.filter(l=>independent(l.id)).length;
    main.innerHTML=heading('LEARNING PATH','每一步，都有明确的产出。','先学知识与示例，再练习和自测。所有章节都可查看，有基础就从合适的位置开始。',button('调整目标与时间','settings','button'))+
    `<div class="tabs">${Object.entries(C.tracks).map(([k,v])=>link(v.short,'#roadmap/'+k,'tab '+(key===k?'active':''))).join('')}</div><section class="panel route-summary"><div><div class="eyebrow">${t.tag} / ${list.length} 节主题课</div><h2>${t.name}</h2><p>${t.desc}</p></div><div class="route-meta"><strong>约 ${Math.ceil(t.hours/state.profile.hours)} 周</strong>按每周 ${state.profile.hours} 小时估算<br>含练习与项目 · 节奏可调整</div></section>
    <div class="two-col"><div>${t.stages.map((s,i)=>{const ls=list.filter(l=>l.stage===i),n=ls.filter(l=>independent(l.id)).length;return `<section class="panel stage"><div class="stage-top"><span class="stage-index">0${i+1}</span><div><h2>${s[0]}</h2><p>${i===0?'从本阶段开始，先建立基础。':'建议先完成上一阶段；可随时查看本阶段内容。'}</p></div>${badge(n+'/'+ls.length+' 实践自检',n===ls.length?'green':'')}</div><div class="lesson-list">${ls.map(l=>`<a class="lesson-link" href="#lesson/${l.id}"><b class="lesson-state ${independent(l.id)?'done':''}">${independent(l.id)?'✓':'›'}</b><span>${l.title}</span><small>${l.minutes} 分钟</small></a>`).join('')}</div><div class="stage-delivery"><strong>阶段产出：</strong>${s[1]}。完成后，检查每节课的变式任务、自测与实践记录。</div></section>`;}).join('')}</div><aside class="stack sticky"><section class="panel"><div class="panel-heading"><h2>继续这条路线</h2>${badge(done+'/'+list.length)}</div><p class="muted">${nextLesson(key).title}</p><div class="progress-track"><span style="width:${pct(done,list.length)}%"></span></div>${link('进入当前课程 →','#lesson/'+nextLesson(key).id,'button primary full mt')}${key!==state.profile.track?button('设为我的优先方向','set-track','text-button mt',`data-track="${key}"`):'<p class="activity-caption">这是你的优先学习方向。</p>'}</section><section class="panel"><h2>每节课的学习节奏</h2><ul class="side-list"><li><b>01 · 理解</b><span>说明知识解决的具体业务问题</span></li><li><b>02 · 复现</b><span>在本机运行示例，核对结果</span></li><li><b>03 · 独立变式</b><span>改一个条件，保存实践证据</span></li><li><b>04 · 自测与复盘</b><span>答题后查看解析，再决定下一步</span></li></ul></section><section class="panel"><h2>搭配这些项目</h2>${C.projects.filter(p=>p.track===key).slice(0,3).map(p=>`<a class="search-result" href="#project/${p.id}">${p.title}<small>${p.time} · ${p.level}</small></a>`).join('')}</section></aside></div>`;
  }
  function lesson(){const l=lessonById.get(route[1]);if(!l){main.innerHTML=empty('课程不存在',link('返回学习路线','#roadmap'));return;}state.lastLesson=l.id;save();const p=progress(l.id);const related=C.lessons.filter(x=>x.track===l.track),next=related[related.indexOf(l)+1];
    main.innerHTML=`<div class="lesson-header">${link('← '+C.tracks[l.track].name,'#roadmap/'+l.track,'back-link')}<div class="eyebrow">阶段 ${l.stage+1} · ${l.minutes} 分钟参考</div><h1>${l.title}</h1><p>${l.goal}</p><div class="lesson-nav"><a href="#" data-scroll="concept">01 知识</a><a href="#" data-scroll="example">02 示例</a><a href="#" data-scroll="practice">03 练习</a><a href="#" data-scroll="check">04 自测</a><a href="#" data-scroll="evidence">05 记录</a></div></div>
    <div class="two-col"><div class="stack lesson-body"><section class="panel" id="concept"><div class="eyebrow">01 / 理解业务与知识</div><h2>先把这件事想清楚</h2>${l.concepts.map(p=>'<p>'+esc(p)+'</p>').join('')}${button(p.read?'已记录阅读 ✓':'我已读懂，记录阅读','read','button small',`data-id="${l.id}"`)}</section>
    <section class="panel" id="example"><div class="eyebrow">02 / 示例与操作</div><h2>运行一次，再改一个输入</h2><div class="code-wrap"><div class="code-header"><span>${esc(l.language)}</span>${button('复制代码','copy-code','',`data-id="${l.id}"`)}</div><pre><code>${esc(l.code)}</code></pre></div><div class="expected">预期结果：${esc(l.expected)}</div><ol>${l.steps.map(s=>'<li>'+esc(s)+'</li>').join('')}</ol><a class="text-button" href="${l.source[1]}" target="_blank" rel="noreferrer">${l.source[0]} ↗</a></section>
    <section class="panel" id="practice"><div class="eyebrow">03 / 独立练习</div><h2>换一个条件，自己完成</h2><p>${l.challenge}</p><div class="notice">先把示例收起来，从输入、规则、输出和边界开始设计。完成后，留下运行命令或测试记录。</div><h3 class="mt">验收清单</h3>${l.checks.map((c,i)=>`<label class="check"><input type="checkbox" data-lesson-check="${i}" ${p.checks?.[i]?'checked':''}>${esc(c)}</label>`).join('')}</section>
    <section class="panel" id="check"><div class="eyebrow">04 / 随堂自测</div><h2>${esc(l.question)}</h2>${l.options.map((o,i)=>`<label class="answer"><input type="radio" name="lesson-answer" value="${i}" ${p.answer===i?'checked':''}><span>${String.fromCharCode(65+i)}. ${esc(o)}</span></label>`).join('')}${button('检查答案','lesson-answer','button small',`data-id="${l.id}"`)}<div id="lessonFeedback" class="mt">${p.correct?`<div class="expected">自测已通过。${esc(l.why)}</div>`:''}</div></section>
    <section class="panel" id="evidence"><div class="eyebrow">05 / 记录可复用的证据</div><h2>我做了什么，怎样验证的？</h2><label class="field"><span>运行命令、结果、修复过程或代码位置</span><textarea id="evidenceText" placeholder="例如：用三组输入验证了重复编号处理；命令为……实际输出……改了规则后……">${esc(p.evidence)}</textarea><small>输入会自动保留在本机。请记录实际验证结果。</small></label><label class="field"><span>这次练习使用的帮助</span><select id="helpLevel"><option value="independent" ${p.help==='independent'?'selected':''}>独立完成</option><option value="hint" ${p.help==='hint'?'selected':''}>使用了提示 / AI 思路</option><option value="reference" ${p.help==='reference'?'selected':''}>参考了完整代码</option></select></label><div class="actions">${button('保存实践自检','complete-lesson','button primary',`data-id="${l.id}"`)}${next?link('下一课 →','#lesson/'+next.id,'button'):link('去项目中应用 →','#projects','button')}</div><p class="activity-caption">${p.practiced?'本课实践记录已保存。':'勾选验收项、通过自测并填写运行证据后，可保存实践自检。'}勾选代表你的自检，代码在本机运行。</p></section></div>
    <aside class="stack sticky"><section class="panel"><h2>本课学习记录</h2><ul class="side-list"><li><b>${p.read?'✓ 已阅读':'○ 待读懂知识'}</b></li><li><b>${p.correct?'✓ 自测已通过':'○ 待完成自测'}</b></li><li><b>${p.practiced?'✓ 已保存实践':'○ 待保存实践证据'}</b><span>${independent(l.id)?'记录为独立练习自检。':p.practiced?'有帮助完成，可以再做一次独立变式。':'一步一步来。'}</span></li></ul>${button(state.bookmarks.includes(l.id)?'★ 已收藏课程':'☆ 收藏这节课','bookmark','button full mt',`data-id="${l.id}"`)}</section><section class="panel tip-panel"><h3>遇到问题时</h3><p>把现象、预期和已尝试的动作写下来，再带着上下文求助。</p>${button('整理问题 / AI 提问','assist','button small',`data-id="${l.id}"`)}</section><section class="panel"><h3>关联项目</h3>${C.projects.filter(pr=>pr.lessons.includes(l.id)).map(pr=>`<a href="#project/${pr.id}" class="search-result">${pr.title}<small>${pr.level} · ${pr.time}</small></a>`).join('')||link('查看全部任务书','#projects','text-button mt')}</section></aside></div>`;
  }
  function projects(){const list=C.projects.filter(p=>(projectFilter==='all'||p.track===projectFilter)&&(p.title+p.tags.join('')+p.desc).toLowerCase().includes(projectSearch.toLowerCase()));
    main.innerHTML=heading('BUILD SOMETHING REAL','项目工坊','从一份任务书开始，按里程碑交付。每个项目都有业务边界、验收要求和独立变更。',badge(C.projects.length+' 份项目任务书','green'))+
      `<div class="toolstrip"><div class="filters">${[['all','全部项目'],...Object.entries(C.tracks).map(([k,t])=>[k,t.short])].map(([k,t])=>button(t,'project-filter','chip '+(projectFilter===k?'active':''),`data-track="${k}"`)).join('')}</div><label><span class="small-label">查找项目 </span><input class="input" style="width:220px" id="projectSearch" placeholder="项目名 / 技术关键词" value="${esc(projectSearch)}"></label></div><div class="project-grid">${list.map((p,i)=>{const n=(state.projects[p.id]?.steps||[]).filter(Boolean).length;return `<article class="panel project-card"><div class="project-cover ${p.track}"><span class="project-monogram">${C.tracks[p.track].icon} /</span>${badge(p.pack?'含练习包':p.level,p.pack?'green':'')}</div><div class="project-body"><h3>${p.title}</h3><p>${p.desc}</p><div class="tags">${p.tags.map(t=>'<span>'+t+'</span>').join('')}</div><div class="progress-caption"><span>${n} / ${p.steps.length} 里程碑自检</span><span>${p.time}</span></div><div class="progress-track"><span style="width:${pct(n,p.steps.length)}%"></span></div><div class="card-bottom"><span>${state.projects[p.id]?.started?'进行中':'随时开始'}</span>${link('查看任务书 ↗','#project/'+p.id,'text-button')}</div></div></article>`;}).join('')}</div>${list.length?'':empty('没有匹配项目','试试其他技术关键词。')}`;
  }
  function project(){const p=C.projects.find(p=>p.id===route[1]);if(!p){main.innerHTML=empty('项目不存在',link('返回项目工坊','#projects'));return;}const data=state.projects[p.id]||{steps:[],evidence:'',started:false};
    main.innerHTML=link('← 返回项目工坊','#projects','back-link')+heading('PROJECT BRIEF / '+C.tracks[p.track].short,p.title,p.desc,button(data.started?'已加入我的项目 ✓':'加入我的项目','join-project','button primary',`data-id="${p.id}"`))+
    `<div class="two-col"><div class="stack"><section class="panel lesson-body"><div class="panel-heading"><h2>业务规则与输入边界</h2>${badge(p.level+' · '+p.time)}</div><ul>${p.rules.map(r=>'<li>'+r+'</li>').join('')}</ul></section><section class="panel"><h2>按里程碑完成</h2>${p.steps.map((s,i)=>`<label class="project-step"><input type="checkbox" data-project-step="${i}" data-id="${p.id}" ${data.steps?.[i]?'checked':''}><span><h3>0${i+1} · ${s[0]}</h3><p>${s[1]}</p><small>交付物：${s[2]}</small></span></label>`).join('')}<p class="activity-caption">里程碑为自检记录，结合下方代码位置和运行证据复盘。</p></section><section class="panel tip-panel"><div class="eyebrow">独立需求变更</div><h2>完成主流程后，再接一项新需求</h2><p>${p.challenge}</p></section><section class="panel"><h2>保存项目现场</h2><label class="field"><span>代码位置、启动方法、测试结果和下一步</span><textarea id="projectEvidence" data-id="${p.id}" placeholder="仓库 / 本机位置：\n运行命令：\n已验证：\n卡住的地方：\n下一步：">${esc(data.evidence)}</textarea><small>自动保留在本机，方便下次继续。</small></label><div class="actions">${button('导出项目任务书与记录','export-project','button primary',`data-id="${p.id}"`)}${link('整理成简历表达 →','#interview','button')}</div></section></div><aside class="stack sticky"><section class="panel"><h2>先补齐这些知识</h2>${p.lessons.map(id=>`<a class="search-result" href="#lesson/${id}">${lessonById.get(id).title}<small>${independent(id)?'已完成独立自检':'可直接学习'}</small></a>`).join('')}</section><section class="panel"><h2>项目材料</h2><p class="activity-caption">${p.pack?'提供可在本机运行的基础参考、样例输入和自检脚本。先按任务书尝试，再对照实现。':'这是一份项目任务书，包含实现步骤与验收要求，完整服务由你在本机实现。'}</p>${p.pack?link('下载练习包 ↓','packs/'+p.pack,'button lime full mt'):''}${button('下载任务书 Markdown','export-project','button full mt',`data-id="${p.id}"`)}</section><section class="panel tip-panel"><h3>面试官可能会问</h3><p>${p.interview}</p>${link('练习项目表达 ↗','#interview','text-button')}</section></aside></div>`;
  }
  function options(values,current){return values.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(current)?'selected':''}>${esc(t)}</option>`).join('');}
  function quiz(){if(state.quizSession){renderQuiz();return;}if(quizResult){renderQuizResult();return;}
    const trackQs=bank.filter(q=>q.track===quizFilters.track),topics=[...new Set(trackQs.map(q=>q.topic))];
    main.innerHTML=heading('PRACTICE & FEEDBACK','测一测，找到下一个需要补的点。','选择主题与题量，逐题作答。提交后显示解析，错题会进入复习清单。',link('查看错题 '+Object.keys(state.wrong).length+' →','#review','button'))+
    `<section class="panel"><div class="quiz-intro"><div><h2>按你正在学的内容组卷</h2><p class="activity-caption">共 ${bank.length} 条题目记录，其中 ${C.checks.length} 道课程自测；旧题库包含 1,170 条场景变式，变式共享知识点。</p></div><div class="quiz-count">${trackQs.length}<span>本方向题目</span></div></div><div class="quiz-config"><label class="field"><span>学习方向</span><select id="quizTrack">${options(Object.entries(C.tracks).map(([k,t])=>[k,t.short]),quizFilters.track)}</select></label><label class="field"><span>知识主题</span><select id="quizTopic">${options([['all','全部主题'],...topics.map(t=>[t,t])],quizFilters.topic)}</select></label><label class="field"><span>内容类型</span><select id="quizKind">${options([['all','全部类型'],['课程自测','课程自测'],['基础题','原基础题'],['场景变式','场景变式']],quizFilters.kind)}</select></label><label class="field"><span>本次题量</span><select id="quizCount">${options([5,10,20,30].map(n=>[n,n+' 题']),quizFilters.count)}</select></label></div><div class="actions">${button('生成练习卷 →','start-quiz','button primary')}<span class="muted" style="font-size:13px">优先抽取未答过的题，选项顺序每次打乱。</span></div></section>
    <div class="grid-2 section-spaced"><section class="panel"><div class="panel-heading"><h2>最近的练习</h2>${badge(state.quizHistory.length+' 次')}</div>${state.quizHistory.slice(-5).reverse().map(h=>`<div class="next-row"><div><h3>${esc(C.tracks[h.track]?.short||'错题复习')}</h3><p>${esc(new Date(h.date).toLocaleString('zh-CN'))}</p></div><strong class="row-link">${h.score} / ${h.total}</strong></div>`).join('')||empty('从第一份练习开始','答题记录会保存在这里。')}</section><section class="panel tip-panel"><h2>答对选择题之后</h2><p>把判断落到一段代码或一条测试上。能复述解析、能处理新条件，才更接近工作中的独立完成。</p>${link('去项目里验证 →','#projects','button small')}</section></div>`;
  }
  function shuffled(list){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
  function startQuiz(wrong=false){
    let pool=wrong?bank.filter(q=>state.wrong[q.id]):bank.filter(q=>q.track===quizFilters.track&&(quizFilters.topic==='all'||q.topic===quizFilters.topic)&&(quizFilters.kind==='all'||q.kind===quizFilters.kind));
    if(!pool.length){toast('当前条件下没有题目，请更换主题或类型。');return;}
    const seen=new Set(state.quizHistory.flatMap(h=>h.ids||[]));pool=[...shuffled(pool.filter(q=>!seen.has(q.id))),...shuffled(pool.filter(q=>seen.has(q.id)))].slice(0,wrong?20:quizFilters.count);
    state.quizSession={track:wrong?'review':quizFilters.track,started:now(),index:0,items:pool.map(q=>({id:q.id,order:shuffled(q.options.map((_,i)=>i))})),answers:{}};quizResult=null;save();if(route[0]!=='quiz')location.hash='#quiz';else renderQuiz();
  }
  function renderQuiz(){const s=state.quizSession,item=s.items[s.index],q=questionById.get(item.id),answered=Object.keys(s.answers).length;
    main.innerHTML=heading('FOCUS MODE','完成这一次练习。','选择后会自动保留；可以前后检查，最后统一提交。',button('暂停，返回题库','pause-quiz','button'))+`<section class="panel quiz-card"><div class="quiz-progress">${s.index+1} / ${s.items.length} · 已作答 ${answered} 题</div><div class="progress-track"><span style="width:${pct(answered,s.items.length)}%"></span></div><div class="tags"><span>${esc(C.tracks[q.track].short)}</span><span>${esc(q.topic)}</span><span>${esc(q.kind)}</span></div><h3>${esc(q.text)}</h3>${item.order.map((original,i)=>`<label class="answer"><input type="radio" name="quiz-answer" value="${original}" ${s.answers[q.id]===original?'checked':''}><span>${String.fromCharCode(65+i)}. ${esc(q.options[original])}</span></label>`).join('')}<div class="quiz-nav">${button('← 上一题','quiz-prev','button',s.index===0?'disabled':'')}<div class="actions">${button('提交答卷','submit-quiz','button primary')}${s.index<s.items.length-1?button('下一题 →','quiz-next','button'):''}</div></div></section><p class="activity-caption">刷新页面可继续当前答卷。选项顺序不会在同一答卷中变化。</p>`;
  }
  function submitQuiz(){const s=state.quizSession;const unanswered=s.items.findIndex(i=>s.answers[i.id]===undefined);if(unanswered>=0){s.index=unanswered;save();renderQuiz();toast('还有未作答的题目，已跳转到第一道。');return;}
    const result=s.items.map(i=>{const q=questionById.get(i.id);return {id:q.id,answer:s.answers[q.id],correct:s.answers[q.id]===q.answer};});const score=result.filter(r=>r.correct).length;
    result.forEach(r=>{if(r.correct)delete state.wrong[r.id];else state.wrong[r.id]={count:(state.wrong[r.id]?.count||0)+1,date:now()};});
    state.quizHistory.push({date:now(),track:s.track,score,total:s.items.length,ids:s.items.map(i=>i.id)});state.quizHistory=state.quizHistory.slice(-200);quizResult={score,total:s.items.length,result};state.quizSession=null;event('quiz','quiz');save();renderNav();renderQuizResult();
  }
  function renderQuizResult(){const r=quizResult;main.innerHTML=heading('PRACTICE REVIEW','把这次练习变成下一步。','逐题查看判断依据，把还不清楚的点带回课程。',button('返回题库','quiz-back','button'))+`<section class="panel"><div class="quiz-intro"><div><div class="result-number">${r.score} <small>/ ${r.total}</small></div><p>${r.score/r.total>=.8?'本次判断比较稳定，试着在代码里完成对应任务。':'先复习错题的概念和例子，再带着新条件练一次。'}</p></div>${link('进入错题复习 →','#review','button primary')}</div>${r.result.map((v,i)=>{const q=questionById.get(v.id);return `<details class="review-row" ${!v.correct?'open':''}><summary>${v.correct?'✓':'○'} ${i+1}. ${esc(q.text)}</summary><p>你的选择：${esc(q.options[v.answer])}</p><p class="success-text">正确答案：${esc(q.options[q.answer])}</p><p>${esc(q.why)}</p>${q.lesson?link('复习对应课程 →','#lesson/'+q.lesson,'text-button'):link('回到 '+C.tracks[q.track].short+' 路线 →','#roadmap/'+q.track,'text-button')}</details>`;}).join('')}</section>`;}
  function review(){const list=bank.filter(q=>state.wrong[q.id]);main.innerHTML=heading('REVIEW QUEUE','把薄弱点一个个补上。','这里保留答错的题。重新答对后移出待复习清单，历史成绩仍然保留。',button('重练错题 →','review-quiz','button primary',list.length?'':'disabled'))+`<section class="panel"><div class="panel-heading"><h2>待复习清单</h2>${badge(list.length+' 题','orange')}</div>${list.map(q=>`<details class="review-row"><summary>${esc(q.text)}</summary><p>知识点：${esc(q.topic)} · 累计答错 ${state.wrong[q.id].count} 次</p><p>正确答案：${esc(q.options[q.answer])}</p><p>${esc(q.why)}</p><div class="actions">${link('回到知识点 →',q.lesson?'#lesson/'+q.lesson:'#roadmap/'+q.track,'button small')}${button('记一条复习笔记','note-question','text-button',`data-id="${q.id}"`)}</div></details>`).join('')||empty('还没有待复习的错题','做一次测验，系统会根据实际答案整理薄弱点。<br>'+link('开始练习 →','#quiz','button mt'))}</section>`;}
  function portfolio(){const chosen=C.projects.find(p=>p.id===state.resume.project)||C.projects[0],list=C.interview.filter(i=>interviewFilter==='all'||i.category===interviewFilter);
    main.innerHTML=heading('CAREER PREPARATION','让你做过的事，说得清楚。','项目复盘、技术追问与简历草稿，围绕真实实践积累。',link('查看我的成果 →','#notes','button'))+
    `<div class="grid-2"><section class="panel"><h2>项目表达草稿</h2><p class="activity-caption">只填你实际完成的内容；未测量的性能、用户量不写进结果。</p><label class="field"><span>选择项目</span><select id="resumeProject">${options(C.projects.map(p=>[p.id,p.title]),chosen.id)}</select></label>${[['role','我负责的模块','例如：导入校验、重复判断与错误清单'],['decision','一个具体技术取舍','为什么选择这个方案，有什么代价？'],['evidence','实际验证结果','测试、运行命令、可复现测量或同学反馈'],['limitation','限制与下一步','目前没有完成什么，准备怎样改进？']].map(([k,t,ph])=>`<label class="field"><span>${t}</span><textarea data-resume="${k}" placeholder="${ph}">${esc(state.resume[k])}</textarea></label>`).join('')}${button('生成并下载 Markdown 草稿','export-resume','button primary')}</section><section class="stack"><div class="panel"><h2>岗位能力检查</h2><p class="activity-caption">下方只统计已保存的独立练习自检，不换算成招聘通过率。</p>${Object.entries(C.tracks).map(([k,t])=>{const ls=C.lessons.filter(l=>l.track===k),n=ls.filter(l=>independent(l.id)).length;return `<div class="mt"><div class="progress-caption"><span>${t.short}</span><span>${n} / ${ls.length}</span></div><div class="progress-track"><span style="width:${pct(n,ls.length)}%"></span></div></div>`;}).join('')}</div><div class="panel tip-panel"><h2>每周做一次模拟表达</h2><p>挑一个项目，用 3 分钟讲背景、职责、难点与验证，再用 5 分钟回答追问。录音后检查哪些地方说得模糊。</p><ul class="side-list"><li><b>30 秒 · 业务背景</b><span>谁遇到了什么问题？</span></li><li><b>90 秒 · 方案与取舍</b><span>你做了什么，为什么这样做？</span></li><li><b>60 秒 · 验证与限制</b><span>怎样确认有效，还有什么边界？</span></li></ul></div></section></div>
    <section class="panel section-spaced"><div class="panel-heading"><div><h2>技术追问练习</h2><p>${C.interview.length} 个追问 · 先写自己的回答，再看组织思路。</p></div></div><div class="filters">${['all','Java','SQL','Python','爬虫','工程'].map(k=>button(k==='all'?'全部':k,'interview-filter','chip '+(interviewFilter===k?'active':''),`data-filter="${k}"`)).join('')}</div>${list.map(i=>`<details class="interview-card"><summary>${esc(i.title)}</summary><div class="tags"><span>${i.category}</span></div><label class="field"><span>我的回答</span><textarea data-interview="${i.id}" placeholder="先用自己的项目回答……">${esc(state.interview[i.id])}</textarea><small>自动保存在本机。</small></label><details><summary>查看组织思路</summary><p>${i.guide}</p>${link('回到相关课程 →','#lesson/'+i.lesson,'text-button')}</details></details>`).join('')}</section>`;
  }
  function notes(){const evidence=C.lessons.filter(l=>progress(l.id).evidence),bookmarks=C.lessons.filter(l=>state.bookmarks.includes(l.id));
    main.innerHTML=heading('MY LEARNING RECORDS','留住解决问题的过程。','把运行结果、踩过的坑和下一步写下来，隔一周也能接着做。',button('备份与恢复','backup','button'))+
    `<div class="two-col"><div class="stack"><section class="panel"><h2>记下一个问题或收获</h2><label class="field"><span>现象、预期、尝试、结论或下一步</span><textarea id="noteDraft" placeholder="我遇到了……原本期待……尝试后发现……下一步……">${esc(state.draftNote)}</textarea></label>${button('保存笔记','save-note','button primary')}</section><section class="panel"><h2>我的笔记 <span class="muted">${state.notes.length}</span></h2>${state.notes.map(n=>`<article class="note-card"><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><div class="actions"><small>${esc(new Date(n.date).toLocaleString('zh-CN'))}</small><div>${n.lesson?link('关联课程','#lesson/'+n.lesson,'text-button'):''} ${button('编辑','edit-note','text-button',`data-id="${esc(n.id)}"`)} ${button('删除','delete-note','text-button danger',`data-id="${esc(n.id)}"`)}</div></div></article>`).join('')||empty('还没有笔记','先保存一次排查过程，下次遇到同类问题就有线索。')}</section><section class="panel"><h2>课程实践与现场记录</h2>${evidence.map(l=>`<details class="review-row"><summary>${l.title} ${progress(l.id).practiced?'· 已实践':'· 草稿'}</summary><p style="white-space:pre-wrap">${esc(progress(l.id).evidence)}</p>${link('继续本课 →','#lesson/'+l.id,'text-button')}</details>`).join('')||empty('从一次实际运行开始','课程中的运行证据会汇集到这里。')}</section></div><aside class="stack"><section class="panel"><h2>收藏的课程</h2>${bookmarks.map(l=>link(l.title+' ↗','#lesson/'+l.id,'search-result')).join('')||'<p class="activity-caption">在课程页面点击收藏，快速回到常用知识。</p>'}</section><section class="panel"><h2>带走你的成果</h2><p class="activity-caption">学习记录保存在当前浏览器。导出 JSON 可以在另一台电脑恢复；本机代码需要另行保存或提交仓库。</p>${button('导出完整学习记录 ↓','export','button full mt')}${button('恢复学习备份','backup','text-button mt')}${state.legacy?'<p class="activity-caption">旧版笔记已迁移，旧进度快照包含在备份中。新课进度按实际学习重新记录。</p>':''}</section></aside></div>`;
  }
  function resources(){main.innerHTML=heading('REFERENCE LIBRARY','带着问题读文档。','资料按具体用途连接到课程；外部阅读不会自动记为独立完成。')+`<div class="resource-grid">${Object.entries(C.sources).map(([key,[name,url]])=>{const usage={java:'语言、集合、异常与对象建模。对照 Java 主线的代码核对用法。',spring:'构建一个 REST 服务，核对项目初始化、Controller 与 JSON 响应。',python:'函数、数据结构、模块与文件处理；先读当前任务需要的章节。',http:'区分连接、读取、写入与连接池超时，设计有边界的请求。',playwright:'学习按角色、标签和稳定属性定位元素，理解等待语义。',test:'用最小输入写断言，测试错误分支并形成回归记录。',sql:'确认提交、回滚与事务边界，配合独立练习数据库验证。',git:'检查差异与暂存范围，留下可审阅的小步提交。'};return `<article class="panel resource"><div class="eyebrow">官方参考</div><h2>${name}</h2><p>${usage[key]}</p><a class="button small" href="${url}" target="_blank" rel="noreferrer">打开文档 ↗</a></article>`;}).join('')}</div><section class="panel section-spaced"><h2>本地实战材料</h2><p class="activity-caption">三个练习包各包含基础参考实现、样例与检查方法。代码在你的电脑运行，学习网站负责组织内容和记录。</p><div class="actions mt">${C.projects.filter(p=>p.pack).map(p=>link(p.title+' ↓','packs/'+p.pack,'button')).join('')}</div></section>`;}
  function openDialog(title,body){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;if(!dialog.open)dialog.showModal();}
  function settings(){openDialog('我的学习节奏',`<p class="muted">主攻一条方向，其他课程仍然随时可学。</p><label class="field"><span>优先方向</span><select id="goalTrack">${options(Object.entries(C.tracks).map(([k,t])=>[k,t.name]),state.profile.track)}</select></label><label class="field"><span>每周可投入时间（小时）</span><input id="weeklyHours" type="number" min="1" max="40" value="${state.profile.hours}"></label><p class="activity-caption">路线周期只是练习与项目的规划估计，按自己的理解程度调整。</p>${button('保存学习计划','save-settings','button primary mt')}`);}
  function download(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
  function exportState(){download('DevPath-学习备份-'+dayKey()+'.json',JSON.stringify({app:'devpath',version:2,exportedAt:now(),state},null,2),'application/json');toast('已生成学习备份，请保管下载文件。');}
  function backup(){openDialog('备份与恢复',`<p>记录保存在当前浏览器。换设备前导出，恢复时会替换当前记录；恢复前会先下载当前备份。</p><div class="actions mt">${button('导出当前备份','export','button primary')}</div><label class="field"><span>选择 DevPath JSON 备份（最大 5 MB）</span><input type="file" id="importFile" accept=".json,application/json"></label><div id="importStatus" role="status"></div>${button('校验并预览备份','inspect-import','button')}`);}
  let pendingImport=null;
  async function inspectImport(){const file=$('#importFile').files[0];if(!file){toast('请选择备份文件。');return;}try{if(file.size>5*1024*1024)throw new Error('文件超过 5 MB');const raw=JSON.parse(await file.text());if(raw.app!=='devpath'||raw.version!==2)throw new Error('请选择从新版 DevPath 导出的备份');pendingImport=normalize(raw.state);$('#importStatus').innerHTML=`<div class="notice">已校验：${pendingImport.notes.length} 条笔记、${Object.keys(pendingImport.lessons).length} 节课记录、${pendingImport.quizHistory.length} 次测验。</div>${button('先导出现有备份，再恢复所选记录','confirm-import','button primary mt')}`;}catch(e){pendingImport=null;$('#importStatus').textContent='无法恢复：'+e.message;}}
  function projectMarkdown(p){const d=state.projects[p.id]||{};return '# '+p.title+'\n\n'+p.desc+'\n\n## 业务规则\n'+p.rules.map(x=>'- '+x).join('\n')+'\n\n## 里程碑\n'+p.steps.map((s,i)=>`- [${d.steps?.[i]?'x':' '}] ${s[0]}：${s[1]}\n  交付物：${s[2]}`).join('\n')+'\n\n## 独立变更\n'+p.challenge+'\n\n## 我的现场记录\n'+(d.evidence||'待填写')+'\n\n## 技术追问\n'+p.interview+'\n';}
  function assist(id){const l=lessonById.get(id);openDialog('整理问题，再带着上下文求助',`<p class="muted">当前课程：${l.title}</p><label class="field"><span>错误现象、预期与已经尝试的动作</span><textarea id="assistInput" placeholder="粘贴必要的错误片段，不包含密码。"></textarea></label><div class="actions">${button('复制上下文提问','copy-assist','button primary',`data-id="${id}"`)}${button('保存为问题笔记','save-assist','button',`data-id="${id}"`)}</div><p class="activity-caption">复制后可粘贴到你使用的 AI 工具。本站不自动调用模型或运行你的代码。</p><a class="text-button" href="https://chat.deepseek.com/" target="_blank" rel="noreferrer">打开 DeepSeek 网页 ↗</a>`);}
  async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制。');}catch{openDialog('手动复制内容',`<textarea class="input" rows="12" readonly>${esc(text)}</textarea>`);}}
  function search(){openDialog('搜索课程、项目与面试题',`<label class="field"><span>知识点、技术名或项目关键词</span><input id="searchInput" placeholder="例如：事务、CSV、重试……" autocomplete="off"></label><div id="searchResults">输入关键词开始查找。</div>`);$('#searchInput').focus();}
  function searchResults(value){const q=value.trim().toLowerCase();if(!q){$('#searchResults').textContent='输入关键词开始查找。';return;}const ls=C.lessons.filter(l=>(l.title+l.goal+l.concepts.join('')).toLowerCase().includes(q)).map(l=>({title:l.title,sub:'课程 · '+C.tracks[l.track].short,href:'#lesson/'+l.id}));const ps=C.projects.filter(p=>(p.title+p.desc+p.tags.join('')).toLowerCase().includes(q)).map(p=>({title:p.title,sub:'项目 · '+p.level,href:'#project/'+p.id}));const qs=window.INTERVIEW_BANK.filter(i=>(i.title+i.category+i.followup).toLowerCase().includes(q)).map(i=>({title:i.title,sub:'面试 · '+i.category,href:'#interview/'+i.id}));$('#searchResults').innerHTML=[...ls.slice(0,6),...ps.slice(0,4),...qs.slice(0,8)].map(r=>`<a class="search-result" href="${r.href}">${esc(r.title)}<small>${esc(r.sub)}</small></a>`).join('')||empty('暂时没有匹配内容','试试更短的关键词。');}
  const actions={
    settings,search,backup,export:exportState,close:()=>dialog.close(),
    menu:()=>{const open=$('#sidebar').classList.toggle('open');$('.mobile-menu').setAttribute('aria-expanded',String(open));},
    minutes:b=>{state.profile.minutes=Number(b.dataset.minutes);save();home();},
    'set-track':b=>{state.profile.track=b.dataset.track;state.lastLesson=nextLesson().id;save();render();toast('已更新优先方向。');},
    'save-settings':()=>{const n=Number($('#weeklyHours').value);if(!Number.isFinite(n)||n<1||n>40){toast('每周时间请输入 1 到 40 小时。');return;}state.profile={...state.profile,track:$('#goalTrack').value,hours:n};state.lastLesson=nextLesson().id;if(save()){dialog.close();render();toast('学习计划已保存。');}},
    read:b=>{const p=progress(b.dataset.id);if(!p.read)event('read',b.dataset.id);state.lessons[b.dataset.id]={...p,read:true};save();lesson();},
    'copy-code':b=>copy(lessonById.get(b.dataset.id).code),
    bookmark:b=>{const id=b.dataset.id;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();const y=scrollY;lesson();scrollTo(0,y);},
    'lesson-answer':b=>{const input=$('input[name="lesson-answer"]:checked');if(!input){toast('先选择一个答案。');return;}const l=lessonById.get(b.dataset.id),correct=Number(input.value)===l.answer;state.lessons[l.id]={...progress(l.id),answer:Number(input.value),correct};if(!correct)state.wrong['check-'+l.id]={count:(state.wrong['check-'+l.id]?.count||0)+1,date:now()};else delete state.wrong['check-'+l.id];save();renderNav();$('#lessonFeedback').innerHTML=`<div class="${correct?'expected':'notice'}">${correct?'回答正确。':'再想一想。正确答案：'+esc(l.options[l.answer])+'。'} ${esc(l.why)}</div>`;},
    'complete-lesson':b=>{const id=b.dataset.id,p=progress(id);if(!p.correct||!p.checks?.every(Boolean)||p.evidence.trim().length<12){toast('请通过自测、勾选全部验收项，并填写至少 12 字的实践记录。');return;}const was=p.practiced;state.lessons[id]={...p,practiced:true,read:true,date:now()};if(!was)event('practice',id);if(save()){const y=scrollY;lesson();scrollTo(0,y);toast(p.help==='independent'?'已保存独立练习自检，下一课已可继续。':'已保存有帮助完成的记录，可以再做一次独立变式。');}},
    'project-filter':b=>{projectFilter=b.dataset.track;projects();},
    'join-project':b=>{const id=b.dataset.id;state.projects[id]={steps:[],evidence:'',...state.projects[id],started:true};save();project();},
    'export-project':b=>{const p=C.projects.find(p=>p.id===b.dataset.id);download(p.title+'-任务书.md',projectMarkdown(p));},
    'start-quiz':()=>startQuiz(false),'review-quiz':()=>{if(state.quizSession){location.hash='#quiz';toast('先继续或结束已有答卷。');}else startQuiz(true);},
    'quiz-prev':()=>{state.quizSession.index--;save();renderQuiz();},'quiz-next':()=>{state.quizSession.index++;save();renderQuiz();},
    'pause-quiz':()=>openDialog('暂停这份练习',`<p>当前答卷会保留，回到测验题库时可以继续。也可以放弃本次未提交的答卷，不计成绩。</p><div class="actions mt">${link('去学习概览','#home','button primary')}${button('放弃未提交答卷','discard-quiz','button')}</div>`),
    'discard-quiz':()=>{state.quizSession=null;save();dialog.close();quiz();},
    'submit-quiz':submitQuiz,'quiz-back':()=>{quizResult=null;quiz();},
    'note-question':b=>{const q=questionById.get(b.dataset.id);state.draftNote=`题目：${q.text}\n我原来怎么想：\n正确判断：${q.options[q.answer]}\n原因：${q.why}\n下一次练习：`;save();location.hash='#notes';},
    'interview-filter':b=>{interviewFilter=b.dataset.filter;const y=scrollY;portfolio();scrollTo(0,y);},
    'export-resume':()=>{const p=C.projects.find(p=>p.id===state.resume.project)||C.projects[0];const r=state.resume;download('项目表达草稿.md',`# ${p.title}\n\n## 业务背景\n${p.desc}\n\n## 我负责的内容\n${r.role||'（待补充真实职责）'}\n\n## 技术选择\n${r.decision||'（待补充取舍）'}\n\n## 实际验证\n${r.evidence||'（待补充运行与测试证据）'}\n\n## 限制与后续\n${r.limitation||'（待补充）'}\n\n## 面试追问\n${p.interview}\n`);},
    'save-note':()=>{const text=state.draftNote.trim();if(text.length<3){toast('先写下一个问题或收获。');return;}state.notes.unshift({id:'note-'+Date.now(),title:text.split('\n')[0].slice(0,40),body:text,date:now(),lesson:''});state.draftNote='';event('note','note');if(save()){notes();toast('笔记已保存。');}},
    'edit-note':b=>{const n=state.notes.find(n=>n.id===b.dataset.id);openDialog('编辑笔记',`<label class="field"><span>笔记内容</span><textarea id="editNoteText">${esc(n.body)}</textarea></label>${button('保存修改','save-edit-note','button primary',`data-id="${esc(n.id)}"`)}`);},
    'save-edit-note':b=>{const n=state.notes.find(n=>n.id===b.dataset.id),text=$('#editNoteText').value.trim();if(!text){toast('笔记不能为空。');return;}n.body=text;n.title=text.split('\n')[0].slice(0,40);if(save()){dialog.close();notes();}},
    'delete-note':b=>openDialog('删除这条笔记？',`<p>这会从当前学习记录中移除该笔记。</p><div class="actions mt">${button('保留','close','button')}${button('删除笔记','confirm-delete-note','button danger',`data-id="${esc(b.dataset.id)}"`)}</div>`),
    'confirm-delete-note':b=>{state.notes=state.notes.filter(n=>n.id!==b.dataset.id);save();dialog.close();notes();toast('笔记已删除；如有此前导出的备份，可从备份恢复。');},
    'inspect-import':inspectImport,'confirm-import':()=>{if(!pendingImport)return;exportState();const original=state;state=pendingImport;if(save()){pendingImport=null;dialog.close();render();toast('备份已恢复。');}else state=original;},
    assist:b=>assist(b.dataset.id),
    'copy-assist':b=>{const l=lessonById.get(b.dataset.id);copy(`我在学习「${l.title}」。\n目标：${l.goal}\n当前示例环境：${l.language}\n独立练习：${l.challenge}\n\n我的问题与尝试：\n${$('#assistInput').value}\n\n请先分析可能原因与最小验证步骤。信息不足请指出。不要声称运行过我的代码，不要直接替我完成整项独立练习。`);},
    'save-assist':b=>{const text=$('#assistInput').value.trim();if(!text){toast('先描述问题。');return;}state.notes.unshift({id:'note-'+Date.now(),title:lessonById.get(b.dataset.id).title+' · 问题',body:text,date:now(),lesson:b.dataset.id});event('note',b.dataset.id);if(save()){dialog.close();toast('问题已保存到笔记。');}}
  };
  const career=window.createCareerUI({C,getState:()=>state,save,esc,link,button,heading,badge,empty,download,toast,independent,event});
  Object.assign(actions,career.actions);
  document.addEventListener('input',e=>career.input(e.target));
  document.addEventListener('change',e=>career.change(e.target));
  document.addEventListener('click',e=>{const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return;}const b=e.target.closest('[data-action]');if(b&&!b.disabled){const fn=actions[b.dataset.action];if(fn)fn(b);}if(e.target.closest('#dialog a[href^="#"]'))dialog.close();if(!e.target.closest('#sidebar')&&!e.target.closest('.mobile-menu')){$('#sidebar').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');}});
  document.addEventListener('input',e=>{const el=e.target;if(el.id==='searchInput')searchResults(el.value);else if(el.id==='evidenceText'){state.lessons[route[1]]={...progress(route[1]),evidence:el.value};save();}else if(el.id==='projectEvidence'){state.projects[el.dataset.id]={steps:[],started:true,...state.projects[el.dataset.id],evidence:el.value};save();}else if(el.id==='noteDraft'){state.draftNote=el.value;save();}else if(el.dataset.resume){state.resume[el.dataset.resume]=el.value;save();}else if(el.dataset.interview){state.interview[el.dataset.interview]=el.value;save();}else if(el.id==='projectSearch'){const pos=el.selectionStart;projectSearch=el.value;projects();$('#projectSearch').focus();$('#projectSearch').setSelectionRange(pos,pos);}});
  document.addEventListener('change',e=>{const el=e.target;
    if(el.matches('[data-lesson-check]')){const p=progress(route[1]);const checks=[...(p.checks||[false,false,false])];checks[Number(el.dataset.lessonCheck)]=el.checked;state.lessons[route[1]]={...p,checks};save();}
    else if(el.name==='lesson-answer'){state.lessons[route[1]]={...progress(route[1]),answer:Number(el.value),correct:false};save();$('#lessonFeedback').textContent='已选择，请点击检查答案。';}
    else if(el.id==='helpLevel'){state.lessons[route[1]]={...progress(route[1]),help:el.value};save();}
    else if(el.matches('[data-project-step]')){const id=el.dataset.id;const p={steps:[],evidence:'',...state.projects[id],started:true};p.steps[Number(el.dataset.projectStep)]=el.checked;state.projects[id]=p;save();}
    else if(el.name==='quiz-answer'){const s=state.quizSession;s.answers[s.items[s.index].id]=Number(el.value);save();const n=Object.keys(s.answers).length;$('.quiz-progress').textContent=`${s.index+1} / ${s.items.length} · 已作答 ${n} 题`;$('.progress-track span').style.width=pct(n,s.items.length)+'%';}
    else if(el.id==='quizTrack'){quizFilters.track=el.value;quizFilters.topic='all';quiz();}
    else if(el.id==='quizTopic')quizFilters.topic=el.value;
    else if(el.id==='quizKind')quizFilters.kind=el.value;
    else if(el.id==='quizCount')quizFilters.count=Number(el.value);
    else if(el.id==='resumeProject'){state.resume.project=el.value;save();}
  });
  document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search();}if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');}});
  window.addEventListener('hashchange',navigate);
  $('#nav').addEventListener('click',e=>{if(e.target.closest('a')){$('#sidebar').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');}});
  navigate();
  if(storageError)toast('读取本机记录遇到问题。原始记录未删除，可先导出或检查浏览器存储。');
})();
